diff --git a/index.html b/index.html
index 21c5c65..67d4de3 100644
--- a/index.html
+++ b/index.html
@@ -38,11 +38,28 @@
         border: 0;
         border-radius: 4px;
         padding: 10px 16px;
+        cursor: pointer;
+      }
+      button:hover {
+        background: #114832;
+      }
+      button:focus-visible {
+        outline: 2px solid #165b41;
+        outline-offset: 3px;
+      }
+      .filter-actions {
+        display: flex;
+        align-items: center;
+        flex-wrap: wrap;
+        gap: 8px 16px;
+      }
+      .filter-actions p {
+        margin: 0;
       }
       table {
         border-collapse: collapse;
-        table-layout: fixed;
-        width: 650px;
+        table-layout: auto;
+        width: auto;
         max-width: 100%;
         background: #fff;
       }
@@ -50,6 +67,9 @@
         text-align: left;
         padding: 12px 0;
       }
+      .period {
+        display: block;
+      }
       th,
       td {
         text-align: left;
@@ -61,11 +81,13 @@
       }
       .service-label {
         display: block;
-        white-space: nowrap;
+        overflow-wrap: anywhere;
       }
       .number {
         font-variant-numeric: tabular-nums;
         text-align: right;
+        white-space: nowrap;
+        padding-inline: 4px;
       }
     </style>
   </head>
@@ -77,9 +99,12 @@
           Synthetic quotes for one origin and destination. Compare complete
           service names, price, and delivery estimates.
         </p>
-        <button id="apply-filter" type="button">
-          Apply ground-service filter
-        </button>
+        <div class="filter-actions">
+          <button id="apply-filter" type="button" aria-controls="comparison">
+            Apply ground-service filter
+          </button>
+          <p id="filter-status" role="status"></p>
+        </div>
       </header>
       <table id="comparison">
         <caption>
@@ -91,9 +116,9 @@
         <thead>
           <tr>
             <th scope="col">Service</th>
-            <th scope="col">Price</th>
-            <th scope="col">Days</th>
-            <th scope="col">On time</th>
+            <th scope="col" class="number">Price</th>
+            <th scope="col" class="number">Days</th>
+            <th scope="col" class="number">On time</th>
           </tr>
         </thead>
         <tbody></tbody>
@@ -124,6 +149,8 @@
         .join("");
       document.querySelector("#apply-filter").addEventListener("click", () => {
         document.body.dataset.state = "filtered";
+        document.querySelector("#filter-status").textContent =
+          "Ground-service filter applied.";
       });
     </script>
   </body>

